-- Lot 800 : les 50 questions successives de l'extension.
--
-- Posees seulement pour les commandes de l'extension, et seulement si elles
-- n'en ont pas deja : ce lot n'efface aucun questionnaire existant.

insert into public.prompt_questions (prompt_id, sort_order, variable, question, choices, trigger_note)
select p.id, d.sort_order, d.variable, d.question, '[]'::jsonb, d.trigger_note
from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-381","sort_order":1,"variable":"reponse_1","question":"Souhaitez-vous fournir le titre et les accroches, ou dois-je créer un texte éditorial fictif très court ?","trigger_note":"Sujet absent ou inexploitable; consentement ou identité ambiguë; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-382","sort_order":1,"variable":"reponse_1","question":"Quel contexte doit évoquer la scène : sortie d’hôtel, restaurant, événement ou rue ?","trigger_note":"Sujet absent ou inexploitable; consentement ou identité ambiguë; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-383","sort_order":1,"variable":"reponse_1","question":"Souhaitez-vous préserver la tenue actuelle ou laisser l’IA créer un look de défilé ?","trigger_note":"Sujet absent ou inexploitable; consentement ou identité ambiguë; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-384","sort_order":1,"variable":"reponse_1","question":"Quel niveau de style voulez-vous : casual, smart, streetwear ou luxe discret ?","trigger_note":"Sujet absent ou inexploitable; consentement ou identité ambiguë; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-385","sort_order":1,"variable":"reponse_1","question":"Avez-vous des mensurations exactes à afficher, ou préférez-vous une version sans données physiques ?","trigger_note":"Sujet absent ou inexploitable; consentement ou identité ambiguë; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-386","sort_order":1,"variable":"reponse_1","question":"Voulez-vous une planche de plusieurs digitals ou une seule image ?","trigger_note":"Sujet absent ou inexploitable; consentement ou identité ambiguë; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-387","sort_ord