r."},{"ref":"RCI-IMG-412","sort_order":1,"variable":"reponse_1","question":"Souhaitez-vous une trame noir et blanc, bichromie ou couleur limitée ?","trigger_note":"Image ou sujet absent; effet demandé ambigu au point de changer la mission; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-413","sort_order":1,"variable":"reponse_1","question":"Quels deux états ou univers doivent alterner dans l’effet lenticulaire ?","trigger_note":"Image ou sujet absent; effet demandé ambigu au point de changer la mission; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-414","sort_order":1,"variable":"reponse_1","question":"Quel type de composition doit être scanné : portrait, objet, fleurs, accessoires ou mélange ?","trigger_note":"Image ou sujet absent; effet demandé ambigu au point de changer la mission; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-415","sort_order":1,"variable":"reponse_1","question":"Quel mouvement ou déplacement doit être décomposé ?","trigger_note":"Image ou sujet absent; effet demandé ambigu au point de changer la mission; texte exact indispensable manquant; contradiction rendant le résultat trompeur."},{"ref":"RCI-IMG-416","sort_order":1,"variable":"reponse_1","question":"Le jumeau doit-il être conceptuel ou fondé sur des données techniques réellement fournies ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-417","sort_order":1,"variable":"reponse_1","question":"Le rendu doit-il être purement esthétique ou représenter des données de scan réellement disponibles ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-418","sort_order":1,"variable":"reponse_1","question":"Quels composants ou étapes du trajet sont confirmés et doivent apparaître ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-419","sort_order":1,"variable":"reponse_1","question":"Disposez-vous de valeurs réelles à afficher ou faut-il rester sur un schéma conceptuel sans chiffres ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-420","sort_order":1,"variable":"reponse_1","question":"Quels départs, arrivées ou câbles sont confirmés et doivent être tracés ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-421","sort_order":1,"variable":"reponse_1","question":"Quel procédé doit être représenté : CNC, laser, découpe, impression 3D ou autre ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-422","sort_order":1,"variable":"reponse_1","question":"Quels joints ou symboles de soudure sont déjà définis dans vos données ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-423","sort_order":1,"variable":"reponse_1","question":"Quelles cotes et tolérances exactes doivent entrer dans la chaîne ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-424","sort_order":1,"variable":"reponse_1","question":"Avez-vous des mesures/simulations acoustiques, ou faut-il produire une illustration conceptuelle clairement signalée ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-425","sort_order":1,"variable":"reponse_1","question":"Disposez-vous d’un angle et d’une portée réels, ou faut-il rester sur une zone indicative ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-426","sort_order":1,"variable":"reponse_1","question":"Avez-vous l’orientation et le lieu/date nécessaires pour une représentation précise, ou souhaitez-vous un schéma conceptuel ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-427","sort_order":1,"variable":"reponse_1","question":"Disposez-vous d’un gabarit ou de dimensions réelles, ou faut-il rester sur une illustration conceptuelle ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-428","sort_order":1,"variable":"reponse_1","question":"Avez-vous des données réelles d’eye-tracking ou souhaitez-vous une estimation heuristique clairement indiquée comme telle ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-429","sort_order":1,"variable":"reponse_1","question":"Disposez-vous de dimensions ou vues supplémentaires, ou faut-il produire uniquement une reconstruction conceptuelle ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."},{"ref":"RCI-IMG-430","sort_order":1,"variable":"reponse_1","question":"Quels points de maintenance sont confirmés par la notice ou vos données ?","trigger_note":"Sujet ou document absent; donnée exacte indispensable non fournie; absence de repère nécessaire à la précision revendiquée; contradiction rendant le résultat techniquement trompeur."}]$raccourcia$::jsonb) as d(
  ref text, sort_order smallint, variable text, question text, trigger_note text
)
join public.prompts p on p.external_ref = d.ref and p.catalog_version = 'v5.2'
where not exists (
  select 1 from public.prompt_questions q
  where q.prompt_id = p.id and q.sort_order = d.sort_order
);

do $ctrl$
declare
  v_total integer;
begin
  select count(*) into v_total
  from public.prompt_questions q
  join public.prompts p on p.id = q.prompt_id and p.catalog_version = 'v5.2';
  if v_total <> 50 then
    raise exception 'Lot 800 : % questions au lieu de 50.', v_total;
  end if;

  -- Le plafond annonce doit valoir ce que la commande peut poser.
  select count(*) into v_total
  from public.prompts p
  where p.catalog_version = 'v5.2'
    and coalesce(p.max_questions, 0)
        <> (select count(*) from public.prompt_questions q where q.prompt_id = p.id);
  if v_total > 0 then
    raise exception '% commandes de l''extension annoncent un plafond faux.', v_total;
  end if;
end $ctrl$;
